#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Build B calls whose delay windows hold 47 and 40 instructions. Usage: IMAGE [be].

Load at 0x1000 with entry 0x1000 and auto-analysis; C6000WideCallWindowTest.java
prepare declares the three functions, as ELF symbols would. An execute packet holds at
most eight instructions, so a window is at most the rest of the branch's packet (7) plus
five full packets (40) (SPRUFE8B 3.5, 4.2.6). Words are TI cl6x 8.3.15 output
(-mv6740 --no_compress), listed by dis6x:

  1000 wide    B.S1 callee || STW B3,*B15--[2] || six ADD/MVK/MPY on .L1 .L2 .S2 .M1 .M2 .D1
       1020    five packets of eight ADD/MVK/MPY on all eight units;
               MVKL/MVKH 0x10c0,B3 on .S2 in the third and fourth: a call returning to 0x10c0
       10c0    LDW *++B15[2],B3 ; NOP 4 ; B B3 ; NOP 5
  10e0 callee  ADD A4,A6,A4 ; B B3 ; NOP 5
  1100 wide40  STW B3,*B15--[2] || B.S1 callee ; the same five packets, B3 set to 0x11a8
       11a8    LDW *++B15[2],B3 ; NOP 4 ; B B3 ; NOP 5
"""

from pathlib import Path
import struct
import sys

WORDS = {
    0x1000: 0x00001C11, 0x1004: 0x01BC54F7, 0x1008: 0x03182059, 0x100C: 0x0318205B,
    0x1010: 0x038000AB, 0x1014: 0x0418CC81, 0x1018: 0x0418CC83, 0x101C: 0x04A42940,
    0x1020: 0x03182059, 0x1024: 0x0318205B, 0x1028: 0x03800129, 0x102C: 0x0380012B,
    0x1030: 0x0418CC81, 0x1034: 0x0418CC83, 0x1038: 0x04A42941, 0x103C: 0x04A42942,
    0x1040: 0x03182059, 0x1044: 0x0318205B, 0x1048: 0x038001A9, 0x104C: 0x038001AB,
    0x1050: 0x0418CC81, 0x1054: 0x0418CC83, 0x1058: 0x04A42941, 0x105C: 0x04A42942,
    0x1060: 0x03182059, 0x1064: 0x0318205B, 0x1068: 0x03800229, 0x106C: 0x0188602B,
    0x1070: 0x0418CC81, 0x1074: 0x0418CC83, 0x1078: 0x04A42941, 0x107C: 0x04A42942,
    0x1080: 0x03182059, 0x1084: 0x0318205B, 0x1088: 0x038002A9, 0x108C: 0x0180006B,
    0x1090: 0x0418CC81, 0x1094: 0x0418CC83, 0x1098: 0x04A42941, 0x109C: 0x04A42942,
    0x10A0: 0x03182059, 0x10A4: 0x0318205B, 0x10A8: 0x03800329, 0x10AC: 0x0380032B,
    0x10B0: 0x0418CC81, 0x10B4: 0x0418CC83, 0x10B8: 0x04A42941, 0x10BC: 0x04A42942,
    0x10C0: 0x01BC52E6, 0x10C4: 0x00006000, 0x10C8: 0x000C0362, 0x10CC: 0x00008000,
    0x10E0: 0x02188078, 0x10E4: 0x000C0362, 0x10E8: 0x00008000, 0x1100: 0x01BC54F7,
    0x1104: 0x0FFFFC10, 0x1108: 0x03182059, 0x110C: 0x0318205B, 0x1110: 0x03800129,
    0x1114: 0x0380012B, 0x1118: 0x0418CC81, 0x111C: 0x0418CC83, 0x1120: 0x04A42941,
    0x1124: 0x04A42942, 0x1128: 0x03182059, 0x112C: 0x0318205B, 0x1130: 0x038001A9,
    0x1134: 0x038001AB, 0x1138: 0x0418CC81, 0x113C: 0x0418CC83, 0x1140: 0x04A42941,
    0x1144: 0x04A42942, 0x1148: 0x03182059, 0x114C: 0x0318205B, 0x1150: 0x03800229,
    0x1154: 0x0188D42B, 0x1158: 0x0418CC81, 0x115C: 0x0418CC83, 0x1160: 0x04A42941,
    0x1164: 0x04A42942, 0x1168: 0x03182059, 0x116C: 0x0318205B, 0x1170: 0x038002A9,
    0x1174: 0x0180006B, 0x1178: 0x0418CC81, 0x117C: 0x0418CC83, 0x1180: 0x04A42941,
    0x1184: 0x04A42942, 0x1188: 0x03182059, 0x118C: 0x0318205B, 0x1190: 0x03800329,
    0x1194: 0x0380032B, 0x1198: 0x0418CC81, 0x119C: 0x0418CC83, 0x11A0: 0x04A42941,
    0x11A4: 0x04A42942, 0x11A8: 0x01BC52E6, 0x11AC: 0x00006000, 0x11B0: 0x000C0362,
    0x11B4: 0x00008000,
}


def main():
    if len(sys.argv) not in (2, 3) or (len(sys.argv) == 3 and sys.argv[2] != "be"):
        raise SystemExit(__doc__)
    endian = ">" if len(sys.argv) == 3 else "<"
    image = bytearray(0x1c0)
    for address, word in WORDS.items():
        struct.pack_into(endian + "I", image, address - 0x1000, word)
    Path(sys.argv[1]).write_bytes(image)


if __name__ == "__main__":
    main()
